async function(variables) {
  var g = new GridWidget(variables.element, variables.dataSource);
  g.editable = false;
	g.sortable = false;
	g.filterable = false;
	g.pageable = false;
	g.scrollable = false;
	g.groupable = false;
  g.columns = [
    {field: "SystemId", title: "[resource_displayname[SystemId]]"},
    {field: "Value", title: "[resource_displayname[Value]]"}
  ];
  variables.companyReferencesGrid = g;
  return g;
}
